//! Camera-light radiance survives compositor AlphaOver and Blur saved-EXR consumers.
//!
//! The committed Blender 5.2.2 inputs and captures are generated by
//! `fixtures/native_oracle/compositor_camera_light_alpha.py`. AlphaOver compares the complete
//! camera-light composite over an opaque background; Blur compares fixed pixels at the geometric
//! edge where the HDR alpha-zero emitter meets the opaque half-plane, through the File Output EXR.

#[path = "common/blender_checked.rs"]
mod blender_checked;
#[path = "common/native_oracle.rs"]
#[expect(
    dead_code,
    reason = "this consumer uses a subset of the shared native oracle helpers"
)]
mod native_oracle;
#[path = "common/process.rs"]
mod process;

use std::{fs, path::Path};

use native_oracle::{TestResult, apply_operations, import_blend, pot, read_scene};
use potter_core::image::decode_pixels;
use potter_core::model::ImageColorspace;
use serde_json::{Value, json};
use tempfile::tempdir;

const ALPHA_OVER_EXR: &[u8] =
    include_bytes!("fixtures/native_oracle/eevee_macos/compositor_alpha_over_camera_light.exr");
const BLUR_SAVED_EXR: &[u8] =
    include_bytes!("fixtures/native_oracle/eevee_macos/compositor_blur_hdr_saved.exr");
const WIDTH: u32 = 64;
const HEIGHT: u32 = 64;
const RGB_TOLERANCE: f64 = 0.03;
const ALPHA_TOLERANCE: f64 = 1.0e-6;

fn fixture(name: &str) -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/native_oracle/eevee_macos")
        .join(name)
}

fn decode_exr(bytes: &[u8], label: &str) -> TestResult<Vec<[f64; 4]>> {
    assert_eq!(
        bytes.get(..4),
        Some(&[0x76, 0x2f, 0x31, 0x01][..]),
        "{label} is not an OpenEXR file"
    );
    let (width, height, pixels) = decode_pixels(bytes, ImageColorspace::Linear)?;
    assert_eq!((width, height), (WIDTH, HEIGHT), "{label} dimensions");
    Ok(pixels)
}

fn active_scene_id(scene: &Value) -> TestResult<String> {
    scene["active_scene"]
        .as_str()
        .map(str::to_owned)
        .ok_or_else(|| "imported scene has no active scene ID".into())
}

fn apply_graph(project: &Path, root: &Path, operations: Value) -> TestResult<()> {
    let result = apply_operations(project, root, operations)?;
    assert_eq!(
        result["result"]["committed"], true,
        "compositor graph apply"
    );
    Ok(())
}

fn render_exr(project: &Path, root: &Path, name: &str) -> TestResult<Vec<u8>> {
    let output_dir = root.join(format!("render_{name}"));
    let mut command = pot();
    command
        .arg("render")
        .arg(project)
        .args(["--engine", "realtime", "--format", "exr", "--out"])
        .arg(&output_dir)
        .arg("--json");
    native_oracle::checked(&mut command, "Potter realtime EXR render")?;
    Ok(fs::read(output_dir.join("frame_0001.exr"))?)
}

fn assert_matches(label: &str, actual: &[[f64; 4]], expected: &[[f64; 4]]) {
    assert_eq!(actual.len(), expected.len(), "{label} pixel count");
    for (index, (actual, expected)) in actual.iter().zip(expected).enumerate() {
        for channel in 0..4 {
            let tolerance = if channel == 3 {
                ALPHA_TOLERANCE
            } else {
                RGB_TOLERANCE
            };
            assert!(
                (actual[channel] - expected[channel]).abs() <= tolerance,
                "{label} EXR pixel {index}, channel {channel}: Potter={} Blender={} tolerance={tolerance}",
                actual[channel],
                expected[channel]
            );
        }
    }
}

fn pixel_at(image: &[[f64; 4]], x: usize, y: usize) -> [f64; 4] {
    image[y * WIDTH as usize + x]
}

fn assert_probe_matches(
    label: &str,
    actual: &[[f64; 4]],
    expected: &[[f64; 4]],
    probes: &[(usize, usize)],
) {
    for &(x, y) in probes {
        let actual = pixel_at(actual, x, y);
        let expected = pixel_at(expected, x, y);
        for channel in 0..4 {
            let tolerance = if channel == 3 {
                ALPHA_TOLERANCE
            } else {
                RGB_TOLERANCE
            };
            assert!(
                (actual[channel] - expected[channel]).abs() <= tolerance,
                "{label} EXR ({x},{y}), channel {channel}: Potter={} Blender={} tolerance={tolerance}",
                actual[channel],
                expected[channel]
            );
        }
    }
}

#[test]
fn camera_light_alpha_survives_native_compositor_and_saved_exr_consumers() -> TestResult {
    let Some(blender) = blender_checked::blender_executable() else {
        if std::env::var_os("POTTER_REQUIRE_BLENDER").is_some() {
            return Err("Blender is required for the compositor camera-light alpha oracle".into());
        }
        eprintln!("skipping compositor camera-light alpha oracle; Blender is unavailable");
        return Ok(());
    };
    let directory = tempdir()?;
    let root = directory.path();
    let alpha_blend = fixture("compositor_alpha_over_scene.blend");
    let (alpha_project, alpha_import) =
        import_blend(&blender, root, "alpha_over_project", &alpha_blend)?;
    assert_eq!(alpha_import["result"]["committed"], true);
    let alpha_scene = read_scene(&alpha_project)?;
    let alpha_scene_id = active_scene_id(&alpha_scene)?;
    apply_graph(
        &alpha_project,
        root,
        json!([
            {"op": "graph.create", "id": "camera_light_alpha_over", "kind": "compositor"},
            {"op": "compositor.node_add", "graph": "camera_light_alpha_over", "id": "layers", "type": "CompositorNodeRLayers"},
            {"op": "compositor.node_add", "graph": "camera_light_alpha_over", "id": "over", "type": "CompositorNodeAlphaOver", "properties": {"background": [0.1, 0.25, 0.5]}},
            {"op": "compositor.node_add", "graph": "camera_light_alpha_over", "id": "composite", "type": "CompositorNodeComposite"},
            {"op": "compositor.link", "graph": "camera_light_alpha_over", "from_node": "layers", "from_socket": "Image", "to_node": "over", "to_socket": "Image"},
            {"op": "compositor.link", "graph": "camera_light_alpha_over", "from_node": "over", "from_socket": "Image", "to_node": "composite", "to_socket": "Image"},
            {"op": "compositor.enable", "target": {"id": alpha_scene_id}, "set": {"enabled": true, "graph": "camera_light_alpha_over"}}
        ]),
    )?;
    let alpha_actual = decode_exr(
        &render_exr(&alpha_project, root, "alpha_over")?,
        "Potter AlphaOver output",
    )?;
    let alpha_expected = decode_exr(ALPHA_OVER_EXR, "Blender AlphaOver capture")?;
    assert!(
        alpha_expected
            .iter()
            .any(|pixel| pixel[3] > 0.99 && pixel[0].max(pixel[1]).max(pixel[2]) > 1.0),
        "native AlphaOver capture contains no HDR camera-light radiance"
    );
    assert_matches("AlphaOver over opaque", &alpha_actual, &alpha_expected);

    let blur_blend = fixture("compositor_blur_hdr_scene.blend");
    let (blur_project, blur_import) = import_blend(&blender, root, "blur_project", &blur_blend)?;
    assert_eq!(blur_import["result"]["committed"], true);
    let blur_scene = read_scene(&blur_project)?;
    let blur_scene_id = active_scene_id(&blur_scene)?;
    let saved_exr = root.join("potter_blur_saved.exr");
    apply_graph(
        &blur_project,
        root,
        json!([
            {"op": "graph.create", "id": "camera_light_blur", "kind": "compositor"},
            {"op": "compositor.node_add", "graph": "camera_light_blur", "id": "layers", "type": "CompositorNodeRLayers"},
            {"op": "compositor.node_add", "graph": "camera_light_blur", "id": "blur", "type": "CompositorNodeBlur", "properties": {"radius": 2}},
            {"op": "compositor.node_add", "graph": "camera_light_blur", "id": "file", "type": "CompositorNodeOutputFile", "properties": {"path": saved_exr.to_string_lossy().into_owned()}},
            {"op": "compositor.node_add", "graph": "camera_light_blur", "id": "composite", "type": "CompositorNodeComposite"},
            {"op": "compositor.link", "graph": "camera_light_blur", "from_node": "layers", "from_socket": "Image", "to_node": "blur", "to_socket": "Image"},
            {"op": "compositor.link", "graph": "camera_light_blur", "from_node": "blur", "from_socket": "Image", "to_node": "file", "to_socket": "Image"},
            {"op": "compositor.link", "graph": "camera_light_blur", "from_node": "blur", "from_socket": "Image", "to_node": "composite", "to_socket": "Image"},
            {"op": "compositor.enable", "target": {"id": blur_scene_id}, "set": {"enabled": true, "graph": "camera_light_blur"}}
        ]),
    )?;
    let _ = render_exr(&blur_project, root, "blur")?;
    let blur_actual = decode_exr(&fs::read(saved_exr)?, "Potter saved Blur EXR")?;
    let blur_expected = decode_exr(BLUR_SAVED_EXR, "Blender saved Blur EXR")?;

    // The half-plane edge at x=32 is fixed by the producer geometry; it crosses the HDR point disc.
    let edge = pixel_at(&blur_expected, 32, 32);
    assert!(
        edge[3] > 0.0 && edge[3] < 1.0,
        "native Blur edge is not fractional-alpha: {edge:?}"
    );
    assert!(
        edge[0].max(edge[1]).max(edge[2]) > 1.0,
        "native Blur edge lost HDR camera-light radiance: {edge:?}"
    );
    assert_probe_matches(
        "saved HDR Blur EXR",
        &blur_actual,
        &blur_expected,
        &[(30, 32), (31, 32), (32, 32), (33, 32), (34, 32)],
    );
    Ok(())
}
